package com.derricklee.ankidict

import java.io.File
import java.security.MessageDigest
import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Pins the gold dashboard's static benchmark asset (app/src/main/assets/benchmark_record.json,
 * generated by scripts/export_benchmark_record.py) against its single doc home
 * docs/extraction-pipeline-state.md (P0 rule 2026-11-14: the doc is the only writer of truth for
 * the headline numbers; the asset is the sanctioned machine copy the app renders). If a benchmark
 * run moves the doc's headline and nobody regenerates the asset, this test fails — the designed
 * tripwire, the same culture as the sha-pinned gate lexicon snapshot.
 */
class BenchmarkRecordParityTest {

    // unit tests run with cwd = module dir on some hosts, repo root on others
    private fun repoFile(vararg candidates: String): File {
        for (c in candidates) {
            val f = File(c)
            if (f.exists()) return f
        }
        throw AssertionError("repo file not found, tried: ${candidates.toList()} (cwd=${File(".").absolutePath})")
    }

    private fun loadAsset(): JSONObject = JSONObject(
        repoFile("src/main/assets/benchmark_record.json", "app/src/main/assets/benchmark_record.json")
            .readText(),
    )

    private fun loadDoc(): String =
        repoFile("../docs/extraction-pipeline-state.md", "docs/extraction-pipeline-state.md").readText()

    @Test
    fun asset_shape_isComplete_andCheckpointValuesPresent() {
        val a = loadAsset()
        for (k in listOf(
            "source_doc", "source_doc_sha256", "recorded", "gold_fixture_photos",
            "sentence_exact", "sentence_exact_pct", "segmentation_exact", "char_accuracy", "caveat",
        )) {
            assertTrue("asset missing '$k'", a.has(k))
        }
        assertTrue("recorded must be a date", Regex("\\d{4}-\\d{2}-\\d{2}").matches(a.getString("recorded")))
        assertTrue("caveat must quote the as-typed floor", a.getString("caveat").contains("FLOOR"))
    }

    @Test
    fun asset_numbers_matchTheDocOfRecord() {
        val a = loadAsset()
        val doc = loadDoc()
        // every headline the app renders must literally appear in the single-home doc
        val goldPhotos = a.getInt("gold_fixture_photos")
        assertTrue("doc must state the gold set", doc.contains("$goldPhotos photos"))
        assertTrue("doc must state sentence exact", doc.contains(a.getString("sentence_exact")))
        assertTrue("doc must state segmentation exact", doc.contains(a.getString("segmentation_exact")))
        assertTrue("doc must state char accuracy", doc.contains(a.getString("char_accuracy")))
    }

    @Test
    fun asset_hash_matchesDocSnapshot_whenDocUntouched() {
        val a = loadAsset()
        val docFile = repoFile("../docs/extraction-pipeline-state.md", "docs/extraction-pipeline-state.md")
        val sha = MessageDigest.getInstance("SHA-256").digest(docFile.readBytes()).joinToString("") { "%02x".format(it) }
        if (sha == a.getString("source_doc_sha256")) {
            // snapshot still current: the doc-contains-numbers test above already pins equality
            assertEquals(64, a.getString("source_doc_sha256").length)
        } else {
            // prose drifted without number drift — regeneration is hygiene, not a content error;
            // numbers equality (the test above) remains the hard gate.
            println("NOTE: doc sha drifted from asset snapshot (${sha.take(12)}… vs ${a.getString("source_doc_sha256").take(12)}…) — rerun scripts/export_benchmark_record.py")
        }
    }
}
